                    </div>
                </div>
            </div>
        `;
    }

    // 渲染所有数据
    function renderAllData() {
        // 渲染首页数据
        renderSugarData();

        // 渲染私信数据
        renderPmData();

        // 渲染个人资料数据
        renderProfileData();
    }

    // 渲染首页数据
    function renderSugarData() {
        const structuredHomeData = parseSugarHomeData(sugarData);

        // 渲染委托广场
        const commissionsContainer = document.getElementById('commissions-container');
        if (commissionsContainer && structuredHomeData.commissions.length > 0) {
