    // 添加解析私信数据的函数
    function parseSugarPmData(rawFullSugarData) {
        const privateMessages = [];

        // 步骤 1: 提取 <pm>...</pm> 标签之间的内容
        let rawPmContent = '';
        const pmContentMatch = rawFullSugarData.match(/<pm>([\s\S]*?)<\/pm>/m);
        if (pmContentMatch && pmContentMatch[1]) {
            rawPmContent = pmContentMatch[1].trim();
        } else {
