    // 添加解析用户个人信息的函数
    function parseSugarProfileData(rawFullSugarData) {
        const userProfile = {};

        // 步骤 1: 提取 <profile>...</profile> 标签之间的内容
        let rawProfileContent = '';
        const profileContentMatch = rawFullSugarData.match(/<profile>([\s\S]*?)<\/profile>/m);
