    // 动画和时间常量 - 将const改为let使它们可以被修改
    let ANIMATION_DURATION = 600; // 动画持续时间（毫秒）
    let ANIMATION_DELAY = 600; // 每条消息之间的延迟时间（毫秒）
    let BUBBLE_DELAY = 400; // 同一发送者的多个气泡之间的延迟（毫秒）

    // DOM 元素
    const chatContainer = document.getElementById('chat-container');
    const chatUserName = document.getElementById('chat-user-name');
    const chatUserStatus = document.getElementById('chat-user-status');
    const commissionStatus = document.getElementById('commission-status');
