    // 存储所有setTimeout的ID
    let messageTimeouts = [];

    // 解析私聊数据
    function parseSugarPrivateChat(rawData) {
        const result = {
            userInfo: {},
            messages: []
        };

        // 1. 提取用户信息
        const userInfoMatch = rawData.match(/\[昵称:(.*?)\|状态:(.*?)\|当前委托:(.*?)\]/);
        if (userInfoMatch) {
            result.userInfo.name = userInfoMatch[1].trim();
            result.userInfo.status = userInfoMatch[2].trim();
            result.userInfo.commission = userInfoMatch[3].trim();
        } else {
            // 兼容旧格式
            const oldUserInfoMatch = rawData.match(/\[昵称:(.*?)\|状态:(.*?)\]/);
            if (oldUserInfoMatch) {
                result.userInfo.name = oldUserInfoMatch[1].trim();
                result.userInfo.status = oldUserInfoMatch[2].trim();
                result.userInfo.commission = "无";
            }
        }

        // 2. 提取消息内容
        const messagesMatch = rawData.match(/<messages>([\s\S]*?)<\/messages>/);
        if (!messagesMatch) return result;

        const messagesContent = messagesMatch[1].trim();
        const lines = messagesContent.split('\n').map(line => line.trim()).filter(line => line);

        // 3. 解析每一行
        lines.forEach(line => {
            // 3.1 解析描述文本
            const narrationMatch = line.match(/<narration>(.*?)<\/narration>/);
            if (narrationMatch) {
                result.messages.push({
                    type: 'narration',
                    text: narrationMatch[1].trim()
                });
                return;
            }

            // 检查是否有发送者信息
            const parts = line.split('|');
            const hasSender = parts.length === 2;
            const sender = hasSender ? parts[0].trim() : null;
            const content = hasSender ? parts[1].trim() : line;

            // 3.2 解析委托消息
            const commissionMatch = content.match(/<commission>(.*?)<\/commission>/);
            if (commissionMatch) {
                const commissionContent = commissionMatch[1].trim();
                // 解析委托内容 [标题][金额]
                const commParts = commissionContent.match(/\[(.*?)\]\[(.*?)\]/);
                if (commParts) {
                    result.messages.push({
                        type: 'commission',
                        title: commParts[1].trim(),
                        amount: commParts[2].trim()
                    });
                }
                return;
            }

            // 3.3 解析同意消息
            const agreeMatch = content.match(/<agree>(.*?)<\/agree>/);
            if (agreeMatch) {
                result.messages.push({
                    type: 'agree',
                    text: agreeMatch[1].trim(),
                    sender: sender,
                    isSelf: sender === '我方'
                });
                return;
            }

            // 3.4 解析拒绝消息
            const refuseMatch = content.match(/<refuse>(.*?)<\/refuse>/);
            if (refuseMatch) {
                result.messages.push({
                    type: 'refuse',
                    text: refuseMatch[1].trim(),
                    sender: sender,
                    isSelf: sender === '我方'
                });
                return;
            }

            // 3.5 解析图片消息
            if (!hasSender) return; // 如果没有发送者，跳过后续解析

            // 检查是否包含图片标签
            const imgMatch = content.match(/<img>(.*?)<\/img>/);
            if (imgMatch) {
                const imgContent = imgMatch[1].trim();

                // 解析图片名称和描述
                // 格式：[图片名称][图片描述]
                const imgParts = imgContent.match(/\[(.*?)\]\[(.*?)\]/);
                if (imgParts) {
                    const imgName = imgParts[1].trim();
                    const imgDesc = imgParts[2].trim();

                    result.messages.push({
                        type: sender === '我方' ? 'self' : 'other',
                        sender: sender,
                        contentType: 'image',
                        imgName: imgName,
                        imgDesc: imgDesc
                    });
                }
                return;
            }

            // 3.6 处理普通文本消息（含多条）
            let bubbles = [];

            // 提取 [xxx] 形式的内容
            const contentMatches = content.match(/\[(.*?)\]/g);
            if (contentMatches) {
                let fullMessage = contentMatches.map(m => m.substring(1, m.length - 1)).join('');

                // 按照/分割成多个气泡
                bubbles = fullMessage.split('/').map(text => text.trim()).filter(text => text);
            }

            // 如果没有找到气泡内容，跳过
            if (bubbles.length === 0) return;

            // 添加消息到结果中
            result.messages.push({
                type: sender === '我方' ? 'self' : 'other',
                sender: sender,
                contentType: 'text',
                bubbles: bubbles
            });
        });

        return result;
    }

    // 渲染消息
    function renderChat(chatData) {
        // 1. 设置用户信息
        if (chatData.userInfo.name) {
            chatUserName.textContent = chatData.userInfo.name;
        }
        if (chatData.userInfo.status) {
            const statusText = chatUserStatus.querySelector('span');
            statusText.textContent = chatData.userInfo.status;

            // 根据状态设置指示点颜色
            const statusIcon = chatUserStatus.querySelector('i');
            if (chatData.userInfo.status === '在线') {
                statusIcon.style.color = '#8df8c5'; // 在线状态为绿色
            } else {
                statusIcon.style.color = '#9d9db5'; // 其他状态为灰色
            }
        }

        // 设置委托状态
        if (chatData.userInfo.commission) {
            const commissionText = commissionStatus.querySelector('span');
            commissionText.textContent = `当前委托: ${chatData.userInfo.commission}`;
        }

        // 2. 渲染消息
        let delay = 0;
        chatData.messages.forEach(message => {
            // 每条消息添加延迟，模拟加载效果
            const timeoutId = setTimeout(() => {
                renderMessage(message);
                // 滚动到底部
                scrollToBottom();
            }, delay);

            // 将timeout ID存储起来，以便于后续快进时清除
            messageTimeouts.push(timeoutId);

            // 增加延迟时间
            delay += ANIMATION_DELAY;

            // 为多条气泡消息设置额外延迟
            if (message.type !== 'narration' && message.contentType === 'text' && message.bubbles && message.bubbles.length > 1) {
                delay += (message.bubbles.length - 1) * BUBBLE_DELAY;
            }
        });
    }

    // 渲染单条消息
    function renderMessage(message) {
        if (message.type === 'narration') {
            // 渲染描述性文本
            const narrationElem = document.createElement('div');
            narrationElem.classList.add('narration');
            narrationElem.textContent = message.text;
            chatContainer.appendChild(narrationElem);
        } else if (message.type === 'commission') {
            // 渲染委托消息
            const commissionElem = document.createElement('div');
            commissionElem.classList.add('commission-message');

            const iconDiv = document.createElement('div');
            iconDiv.classList.add('commission-icon');
            const icon = document.createElement('i');
            icon.classList.add('fa', 'fa-file-contract');
            iconDiv.appendChild(icon);
            commissionElem.appendChild(iconDiv);

            const titleDiv = document.createElement('div');
            titleDiv.classList.add('commission-title');
            titleDiv.textContent = message.title;
            commissionElem.appendChild(titleDiv);

            const amountDiv = document.createElement('div');
            amountDiv.classList.add('commission-amount');
            amountDiv.textContent = message.amount;
            commissionElem.appendChild(amountDiv);

            chatContainer.appendChild(commissionElem);
        } else if (message.type === 'agree' || message.type === 'refuse') {
            // 渲染同意/拒绝消息
            const statusRow = document.createElement('div');
            statusRow.classList.add('message-row');

            // 根据发送者设置位置
            if (message.isSelf) {
                statusRow.classList.add('message-self-end'); // 自己发送的，靠右显示
            } else {
                // 添加头像
                const avatar = document.createElement('div');
                avatar.classList.add('message-avatar');
                // const avatarIcon = document.createElement('i');
                const avatarImage = document.createElement('img');
                avatarImage.src = avatarURL[message.sender] || avatarURL['default'];
                avatarImage.alt = message.sender;
                avatar.appendChild(avatarImage);
                statusRow.appendChild(avatar);
            }

            const statusContent = document.createElement('div');
            statusContent.classList.add('message-content');

            // 如果有发送者且不是自己，显示发送者名称
            if (message.sender && !message.isSelf) {
                const senderElem = document.createElement('div');
                senderElem.classList.add('message-sender');
                senderElem.textContent = message.sender;
                statusContent.appendChild(senderElem);
            }

            const statusBubble = document.createElement('div');
            statusBubble.classList.add('message-bubble');
            statusBubble.classList.add(message.type === 'agree' ? 'message-agree' : 'message-refuse');

            // 添加图标和文本
            const icon = document.createElement('i');
            icon.classList.add('fa', message.type === 'agree' ? 'fa-check-circle' : 'fa-times-circle');
            icon.style.marginRight = '8px';
            statusBubble.appendChild(icon);

            const textSpan = document.createElement('span');
            textSpan.textContent = message.text;
            statusBubble.appendChild(textSpan);

            statusContent.appendChild(statusBubble);
            statusRow.appendChild(statusContent);
            chatContainer.appendChild(statusRow);
        } else {
            // 渲染普通消息或图片消息
            // 创建消息行
            const messageRow = document.createElement('div');
            messageRow.classList.add('message-row');

            if (message.type === 'self') {
                // 自己发送的消息
                messageRow.classList.add('message-self-end');

                // 创建消息内容容器
                const messageContent = document.createElement('div');
                messageContent.classList.add('message-content');
                messageRow.appendChild(messageContent);

                if (message.contentType === 'image') {
                    // 渲染图片消息
                    const messageBubble = createImageBubble(message, 'message-self');
                    messageContent.appendChild(messageBubble);
                } else {
                    // 渲染多个文本气泡
                    message.bubbles.forEach((bubbleText, index) => {
                        const messageBubble = document.createElement('div');
                        messageBubble.classList.add('message-bubble', 'message-self');
                        messageBubble.textContent = bubbleText;
                        messageBubble.style.animationDelay = `${index * BUBBLE_DELAY}ms`;
                        messageContent.appendChild(messageBubble);
                    });
                }
            } else {
                // 对方发送的消息
                // 头像
                const avatar = document.createElement('div');
                avatar.classList.add('message-avatar');
                // const avatarIcon = document.createElement('i');
                const avatarImage = document.createElement('img');
                avatarImage.src = avatarURL[message.sender] || avatarURL['default'];
                avatarImage.alt = message.sender;
                avatar.appendChild(avatarImage);
                messageRow.appendChild(avatar);

                // 消息内容容器
                const messageContent = document.createElement('div');
                messageContent.classList.add('message-content');

                // 发送者名称
                const senderElem = document.createElement('div');
                senderElem.classList.add('message-sender');
                senderElem.textContent = message.sender;
                messageContent.appendChild(senderElem);

                if (message.contentType === 'image') {
                    // 渲染图片消息
                    const messageBubble = createImageBubble(message, 'message-other');
                    messageContent.appendChild(messageBubble);
                } else {
                    // 渲染多个文本气泡
                    message.bubbles.forEach((bubbleText, index) => {
                        const messageBubble = document.createElement('div');
                        messageBubble.classList.add('message-bubble', 'message-other');
                        messageBubble.textContent = bubbleText;
                        messageBubble.style.animationDelay = `${index * BUBBLE_DELAY}ms`;
                        messageContent.appendChild(messageBubble);
                    });
                }

                messageRow.appendChild(messageContent);
            }

            chatContainer.appendChild(messageRow);
        }
    }

    // 创建图片消息气泡
    function createImageBubble(message, bubbleClass) {
        const messageBubble = document.createElement('div');
        messageBubble.classList.add('message-bubble', bubbleClass, 'message-image');

        // 创建图片占位符
        const imagePlaceholder = document.createElement('div');
        imagePlaceholder.classList.add('image-placeholder');

        // 图片图标或实际图片
        const imageIcon = document.createElement('i');
        imageIcon.classList.add('fa', 'fa-image');
        imagePlaceholder.appendChild(imageIcon);

        // 图片名称
        const imageName = document.createElement('div');
        imageName.classList.add('image-name');
        imageName.textContent = "点击查看图片";
        imagePlaceholder.appendChild(imageName);

        // 将占位符添加到气泡
        messageBubble.appendChild(imagePlaceholder);

        // 存储图片信息，用于点击时显示
        messageBubble.dataset.imgName = message.imgName;
        messageBubble.dataset.imgDesc = message.imgDesc;

        // 添加点击事件
        messageBubble.addEventListener('click', function() {
            showImageModal(this.dataset.imgName, this.dataset.imgDesc);
        });

        return messageBubble;
    }

    // 显示图片查看弹窗
    function showImageModal(imgName, imgDesc) {
        const imageModal = document.getElementById('image-modal');
        const imageDesc = document.getElementById('image-desc');
        const imageDisplay = document.querySelector('.image-modal-display');

        // 清空现有内容
        imageDisplay.innerHTML = '';

        // 设置图片信息
        imageDesc.textContent = imgDesc;

        // 检查是否有对应的图片URL
        if (imgURL[imgName]) {
            const img = document.createElement('img');
            img.src = imgURL[imgName];
            img.alt = imgName;

            // 添加图片加载完成后的处理
            img.onload = function() {
                // 根据图片实际比例调整容器
                const ratio = img.naturalWidth / img.naturalHeight;

                if (ratio > 1) {
                    // 横向图片
                    imageDisplay.style.maxWidth = '280px';
                    imageDisplay.style.maxHeight = 'auto';
                } else {
                    // 纵向图片
                    imageDisplay.style.maxHeight = '280px';
                    imageDisplay.style.maxWidth = 'auto';
                }

                // 重新居中弹窗内容
                setTimeout(() => {
                    imageModal.classList.add('active');
                }, 50);
            };

            imageDisplay.appendChild(img);
        } else {
            // 没有对应图片，显示图标
            const icon = document.createElement('i');
            icon.classList.add('fa', 'fa-image');
            imageDisplay.appendChild(icon);
            imageModal.classList.add('active');
        }

        // 显示弹窗
        imageModal.classList.add('active');

        // 点击背景关闭弹窗
        imageModal.onclick = function(event) {
            if (event.target === imageModal) {
                hideImageModal();
            }
        };
    }

    // 隐藏图片查看弹窗
    function hideImageModal() {
        const imageModal = document.getElementById('image-modal');
        imageModal.classList.remove('active');
    }

    // 滚动到底部
    function scrollToBottom() {
        const sugarContent = document.querySelector('.sugar-content');
        sugarContent.scrollTop = sugarContent.scrollHeight;
    }

    // 发送新消息
    function sendNewMessage() {
        const text = messageInput.value.trim();
        if (!text) return;

        // 创建新消息对象
        const newMessage = {
            type: 'self',
            sender: '我方',
            contentType: 'text',  // 添加contentType字段
            bubbles: [text]
        };

        // 渲染新消息
        renderMessage(newMessage);

        // 滚动到底部
        setTimeout(scrollToBottom, 50);

        // 清空输入框
        messageInput.value = '';
        triggerSlash(`/send 回复私聊->${text}`);
    }

    // 显示发起委托弹窗
    function showCommissionModal() {
        commissionModal.classList.add('active');
        commissionAmount.focus();

        // 点击背景关闭弹窗
        commissionModal.onclick = function(event) {
            if (event.target === commissionModal) {
                hideCommissionModal();
            }
        };
    }

    // 隐藏发起委托弹窗
    function hideCommissionModal() {
        commissionModal.classList.remove('active');
        commissionTitle.value = '';
        commissionAmount.value = '';
    }

    // 提交委托
    function submitCommission() {
        const title = commissionTitle.value.trim();
        const amount = commissionAmount.value.trim();
        if (!amount || !title) return;

        // 触发发送委托的命令
        triggerSlash(`/send 回复私聊->[发起委托]委托名: ${title}, 委托金额: ${amount}`);

        // 隐藏弹窗
        hideCommissionModal();
    }

    // 页面加载完成后初始化
    document.addEventListener('DOMContentLoaded', function() {
        // 解析并渲染聊天数据
        if (sugarPrivateData) {
            const chatData = parseSugarPrivateChat(sugarPrivateData);
            renderChat(chatData);
        } else {
            // 如果没有数据，显示默认消息
            chatUserName.textContent = "未知用户";
            const defaultNarration = document.createElement('div');
            defaultNarration.classList.add('narration');
            defaultNarration.textContent = "暂无聊天记录";
            chatContainer.appendChild(defaultNarration);
        }

        // 绑定发送按钮事件
        sendButton.addEventListener('click', sendNewMessage);

        // 绑定回车键发送事件
        messageInput.addEventListener('keypress', function(event) {
            if (event.key === 'Enter') {
                sendNewMessage();
            }
        });

        // 绑定添加按钮事件，弹出委托弹窗
        addButton.addEventListener('click', showCommissionModal);

        // 绑定委托弹窗按钮事件
        commissionConfirm.addEventListener('click', submitCommission);
        commissionCancel.addEventListener('click', hideCommissionModal);

        // 绑定委托金额输入框回车事件
        commissionAmount.addEventListener('keypress', function(event) {
            if (event.key === 'Enter') {
                submitCommission();
            }
        });

        // 绑定委托标题输入框回车事件
        commissionTitle.addEventListener('keypress', function(event) {
            if (event.key === 'Enter') {
                commissionAmount.focus(); // 按回车后焦点移到金额输入框
            }
        });

        // 绑定返回按钮事件
        document.getElementById('back-button').addEventListener('click', function() {
            triggerSlash(`/send 返回主页`);
        });

        // 绑定快进按钮事件
        document.getElementById('fast-forward-button').addEventListener('click', function() {
            // 实现快进功能
            // 这里可以根据需要添加快进逻辑
            console.log("快进按钮被点击");
        });

        // 快进按钮功能
        const fastForwardButton = document.getElementById('fast-forward-button');
        let isAccelerating = false;
        let pressTimer;

        // 按下按钮开始计时
        fastForwardButton.addEventListener('mousedown', function() {
            pressTimer = setTimeout(function() {
                isAccelerating = true;
                fastForwardButton.classList.add('active');
                accelerateAnimations();
            }, 300); // 300ms后判定为长按
        });

        // 松开按钮停止计时并重置状态
        fastForwardButton.addEventListener('mouseup', function() {
            clearTimeout(pressTimer);
            if (isAccelerating) {
                isAccelerating = false;
                fastForwardButton.classList.remove('active');
                resetAnimationSpeed();
            }
        });

        // 鼠标移出按钮时也停止计时
        fastForwardButton.addEventListener('mouseleave', function() {
            clearTimeout(pressTimer);
            if (isAccelerating) {
                isAccelerating = false;
                fastForwardButton.classList.remove('active');
                resetAnimationSpeed();
            }
        });

        // 触摸事件支持
        fastForwardButton.addEventListener('touchstart', function(e) {
            e.preventDefault(); // 防止触摸事件的默认行为
            pressTimer = setTimeout(function() {
                isAccelerating = true;
                fastForwardButton.classList.add('active');
                accelerateAnimations();
            }, 300);
        });

        fastForwardButton.addEventListener('touchend', function() {
            clearTimeout(pressTimer);
            if (isAccelerating) {
                isAccelerating = false;
                fastForwardButton.classList.remove('active');
                resetAnimationSpeed();
            }
        });

        // 加速动画显示 - 全面重写
        function accelerateAnimations() {
            // 1. 取消所有待执行的setTimeout
            messageTimeouts.forEach(timeoutId => clearTimeout(timeoutId));
            messageTimeouts = []; // 清空数组

            // 2. 立即显示所有未显示的消息和动画
            const pendingRows = document.querySelectorAll('.message-row, .narration, .commission-message');
            pendingRows.forEach(element => {
                // 设置为可见
                element.style.opacity = "1";
                element.style.animationDuration = "0s";

                // 处理该行内的所有气泡
                const bubbles = element.querySelectorAll('.message-bubble');
                bubbles.forEach(bubble => {
                    bubble.style.opacity = "1";
                    bubble.style.animationDuration = "0s";
                    bubble.style.animationDelay = "0s";
                });
            });

            // 3. 重新渲染未显示的消息(如果聊天数据已加载)
            if (sugarPrivateData) {
                // 获取尚未渲染的消息
                const chatData = parseSugarPrivateChat(sugarPrivateData);
                const renderedCount = document.querySelectorAll('.message-row, .narration, .commission-message').length;

                // 如果有未渲染的消息，立即渲染它们
                if (renderedCount < chatData.messages.length) {
                    for (let i = renderedCount; i < chatData.messages.length; i++) {
                        renderMessage(chatData.messages[i]);
                    }
                }
            }

            // 4. 滚动到底部
            scrollToBottom();
        }

        // 恢复正常动画速度
        function resetAnimationSpeed() {
            ANIMATION_DURATION = 600;
            ANIMATION_DELAY = 600;
            BUBBLE_DELAY = 400;
        }
    });
    </script>
</body>
</html>
