    /**
     * 解析 SugarApp 首页的纯文本数据。
     * @param {string} rawFullSugarData - 包含 <home>...</home> 标签在内的完整原始字符串数据。
     * @returns {object} 解析后的数据对象，包含 commissions, featuredProfiles, 和 trendingTopics 数组。
     */
     // Helper function to extract content between section tags (e.g., [commissions_feed]...[/commissions_feed])
    function extractSectionContent(sectionName, rawContent) {
        const regex = new RegExp(`\\[${sectionName}\\]([\\s\\S]*?)\\[\\/${sectionName}\\]`, 'm');
        const match = rawContent.match(regex); // 注意：这里使用 rawHomeContent
        return match && match[1] ? match[1].trim() : '';
    }

    // Helper function to parse individual item lines
    // Example line: [键1:值1|键2:值2a,值2b|键3:值3]
    function parseItemLine(itemLine) {
        const item = {};
        if (!itemLine.startsWith('[') || !itemLine.endsWith(']')) {
            console.warn('跳过格式错误的条目行:', itemLine);
            return null;
        }

        // 移除首尾的 '[' 和 ']'
        const content = itemLine.substring(1, itemLine.length - 1);

        // 按 '|' 分割成字段
        const fields = content.split('|');

        fields.forEach(field => {
            const parts = field.split(/:(.+)/); // 按第一个冒号分割，保留冒号后的所有内容
            if (parts.length === 3) { 
                const key = parts[0].trim();
                let value = parts[1].trim();

                // 特殊处理需要转为数组的字段
                if (key === '标签') {
                    value = value.split(',').map(tag => tag.trim()).filter(tag => tag); 
                }
                item[key] = value;
            } else {
                console.warn('跳过格式错误的字段:', field, '在行内:', itemLine);
            }
        });
        return Object.keys(item).length > 0 ? item : null;
    }

    function parseSugarHomeData(rawFullSugarData) {
        const parsedData = {
            commissions: [],
            featuredProfiles: [],
            trendingTopics: []
        };

        // 步骤 1: 提取 <home>...</home> 标签之间的内容
        let rawHomeContent = '';
        const homeContentMatch = rawFullSugarData.match(/<home>([\s\S]*?)<\/home>/m);
        if (homeContentMatch && homeContentMatch[1]) {
            rawHomeContent = homeContentMatch[1].trim();
        } else {
            console.warn("<home>...</home> 标签未找到或内容为空。");
            return parsedData; // 如果没有 home 内容，直接返回空结构
        }

        // --- 后续逻辑与之前相同，但操作对象是 rawHomeContent ---

        // 2. 解析委托广场 (Commissions Feed)
        const commissionsContent = extractSectionContent('commissions_feed', rawHomeContent);
        if (commissionsContent) {
            const commissionLines = commissionsContent.split('\n').map(line => line.trim()).filter(line => line);
            commissionLines.forEach(line => {
                const commission = parseItemLine(line);
                if (commission) {
                    parsedData.commissions.push(commission);
                }
            });
        }

        // 3. 解析推荐用户 (Featured Profiles)
        const profilesContent = extractSectionContent('featured_profiles', rawHomeContent);
        if (profilesContent) {
            const profileLines = profilesContent.split('\n').map(line => line.trim()).filter(line => line);
            profileLines.forEach(line => {
                const profile = parseItemLine(line);
                if (profile) {
                    parsedData.featuredProfiles.push(profile);
                }
            });
        }

        // 4. 解析热门话题 (Trending Topics)
        const topicsContent = extractSectionContent('trending_topics', rawHomeContent);
        if (topicsContent) {
            const topicLines = topicsContent.split('\n').map(line => line.trim()).filter(line => line);
            topicLines.forEach(line => {
                const topic = parseItemLine(line);
                if (topic) {
                    parsedData.trendingTopics.push(topic);
                }
            });
        }

        return parsedData;
    }

    // 渲染委托卡片
    function renderCommissionCard(commission, index) {
        let tagsHtml = '';
        if (commission['标签'] && Array.isArray(commission['标签'])) {
