                <div class="user-info">${profile['简介']}</div>
                <div class="user-info"><i class="fa fa-map-marker-alt"></i> ${profile['所在地区']}</div>
                ${isVerified ? '<div class="user-verified"><i class="fa fa-check-circle"></i> 已认证</div>' : ''}
                <div class="user-status ${isOnline ? 'user-online' : 'user-offline'}">
                    <i class="fa ${isOnline ? 'fa-circle' : 'fa-clock'}"></i> 
                    ${isOnline ? '在线' : profile['最后在线']}
                </div>
            </div>
        `;
    }

    // 渲染话题项
    function renderTopicItem(topic) {
        return `
            <div class="topic-item">
                <div class="topic-title">${topic['话题标题']}</div>
                <div class="topic-stats">
                    <div class="topic-stat">
