        // 渲染推荐用户
        const profilesCarousel = document.getElementById('profiles-carousel');
        if (profilesCarousel && structuredHomeData.featuredProfiles.length > 0) {
            profilesCarousel.innerHTML = structuredHomeData.featuredProfiles.map((profile, index) => 
                renderProfileCard(profile, index)
            ).join('');
        } else if (profilesCarousel) {
