        }

        // 渲染热门话题
        const topicsList = document.getElementById('topics-list');
        if (topicsList && structuredHomeData.trendingTopics.length > 0) {
            topicsList.innerHTML = structuredHomeData.trendingTopics.map(renderTopicItem).join('');
        } else if (topicsList) {
            topicsList.innerHTML = '<p>暂无热门话题</p>';
