    // 显示弹窗
    function showModal(title, text, confirmCallback) {
        const modal = document.getElementById('sugar-modal');
        const modalTitle = document.getElementById('modal-title');
        const modalText = document.getElementById('modal-text');
        const confirmBtn = document.getElementById('modal-confirm');
        const cancelBtn = document.getElementById('modal-cancel');

        // 设置弹窗内容
        modalTitle.textContent = title;
        modalText.textContent = text;

        // 显示弹窗
        modal.classList.add('active');

        // 按钮事件处理
        confirmBtn.onclick = function() {
            // 执行确认回调
            if (typeof confirmCallback === 'function') {
                confirmCallback();
            }
            // 关闭弹窗
            hideModal();
        };

        cancelBtn.onclick = hideModal;

        // 点击弹窗背景关闭弹窗
        modal.onclick = function(event) {
            if (event.target === modal) {
                hideModal();
            }
        };
    }

    // 隐藏弹窗
    function hideModal() {
        const modal = document.getElementById('sugar-modal');
        modal.classList.remove('active');
    }

    // 添加解析私信数据的函数
    function parseSugarPmData(rawFullSugarData) {
        const privateMessages = [];

        // 步骤 1: 提取 <pm>...</pm> 标签之间的内容
        let rawPmContent = '';
        const pmContentMatch = rawFullSugarData.match(/<pm>([\s\S]*?)<\/pm>/m);
        if (pmContentMatch && pmContentMatch[1]) {
            rawPmContent = pmContentMatch[1].trim();
        } else {
            console.warn("<pm>...</pm> 标签未找到或内容为空。");
            return privateMessages;
        }

        // 步骤 2: 解析每条私信记录
        const messageLines = rawPmContent.split('\n').map(line => line.trim()).filter(line => line);
        messageLines.forEach(line => {
            const message = parseItemLine(line); // 复用之前的解析函数
            if (message) {
                privateMessages.push(message);
            }
        });

        return privateMessages;
    }

    // 渲染私信列表项
    function renderMessageItem(message, index) {
        const unreadCount = parseInt(message['未读消息']) || 0;
        const avatar = avatarURL[message['昵称']] || avatarURL['default'];

        return `
            <div class="message-item" data-type="message" data-index="${index}">
                <div class="message-avatar">
                    <img src="${avatar}" alt="${message['昵称']}">
                </div>
                <div class="message-content">
                    <div class="message-header">
                        <div class="message-name">${message['昵称']}</div>
                        <div class="message-time"><i class="fa fa-clock"></i> ${message['上次回复']}</div>
                    </div>
                    <div class="message-preview">${message['消息']}</div>
                </div>
                ${unreadCount > 0 ? `<div class="message-badge">${unreadCount}</div>` : ''}
            </div>
        `;
    }

    // 渲染私信数据
    function renderPmData() {
        const privateMessages = parseSugarPmData(sugarData);

        // 渲染私信列表
        const messageList = document.getElementById('message-list');
        if (messageList && privateMessages.length > 0) {
            messageList.innerHTML = privateMessages.map((message, index) => 
                renderMessageItem(message, index)
            ).join('');

            // 添加私信点击事件
            addMessageClickEvents(privateMessages);
        } else if (messageList) {
            messageList.innerHTML = '<p>暂无私信消息</p>';
        }
    }

    // 添加私信点击事件
    function addMessageClickEvents(privateMessages) {
        document.querySelectorAll('.message-item').forEach(item => {
            item.addEventListener('click', function() {
                const index = this.getAttribute('data-index');
                const message = privateMessages[index];

                showModal(
                    '进入私聊', 
                    `您确定要与${message['昵称']}开始私聊吗？`,
                    function() {
                        // 确认后的处理逻辑
                        console.log('进入私聊:', message);
                        triggerSlash(`/send 进入私聊->私聊对象${message['昵称']}`);
                    }
                );
            });
        });
    }

    // 添加解析用户个人信息的函数
    function parseSugarProfileData(rawFullSugarData) {
        const userProfile = {};

        // 步骤 1: 提取 <profile>...</profile> 标签之间的内容
        let rawProfileContent = '';
        const profileContentMatch = rawFullSugarData.match(/<profile>([\s\S]*?)<\/profile>/m);
        if (profileContentMatch && profileContentMatch[1]) {
            rawProfileContent = profileContentMatch[1].trim();
        } else {
            console.warn("<profile>...</profile> 标签未找到或内容为空。");
            return userProfile;
        }

        // 步骤 2: 解析用户信息
        const profileLines = rawProfileContent.split('\n').map(line => line.trim()).filter(line => line);
        profileLines.forEach(line => {
            const profile = parseItemLine(line);
            if (profile) {
                // 将解析到的所有属性合并到 userProfile 对象中
                Object.assign(userProfile, profile);
            }
        });

        return userProfile;
    }

    // 渲染用户个人信息
    function renderProfileData() {
        const userProfile = parseSugarProfileData(sugarData);
        const profileContainer = document.getElementById('user-profile-container');

        if (profileContainer && Object.keys(userProfile).length > 0) {
            // 确定身份组样式类
            let membershipClass = 'user-normal';
            let membershipIcon = 'fa-user';

            if (userProfile['身份组'] === 'VIP') {
                membershipClass = 'user-vip';
                membershipIcon = 'fa-crown';
            } else if (userProfile['身份组'] === 'SVIP') {
                membershipClass = 'user-svip';
                membershipIcon = 'fa-gem';
            }

            // 生成用户头像URL
            const avatarUrl = avatarURL[userProfile['昵称']] || "./User Avatars/user-default.png";

            // 渲染用户信息卡片
            profileContainer.innerHTML = `
                <div class="user-profile-card">
                    <div class="user-profile-avatar">
                        <img src="${avatarUrl}" alt="${userProfile['昵称']}">
                    </div>
                    <div class="user-profile-name">${userProfile['昵称']}</div>
                    <div class="user-profile-info">
                        <div class="user-profile-item">
                            <i class="fa fa-venus-mars"></i>
                            <span class="user-profile-label">性别</span>
                            <span class="user-profile-value">${userProfile['性别'] || '未设置'}</span>
                        </div>
                        <div class="user-profile-item">
                            <i class="fa ${membershipIcon}"></i>
                            <span class="user-profile-label">会员等级</span>
                            <span class="user-profile-value">
                                <span class="user-membership ${membershipClass}">
                                    <i class="fa ${membershipIcon}"></i> ${userProfile['身份组']}
                                </span>
                            </span>
                        </div>
                    </div>
                </div>
            `;
        } else if (profileContainer) {
            profileContainer.innerHTML = '<p>暂无个人信息</p>';
        }
    }
    </script>
