    <script>
        let stars = [];
        const starCount = 100;

        function setup() {
            let canvas = createCanvas(windowWidth, windowHeight);
            canvas.parent('p5Canvas');

            // 初始化星星
            for (let i = 0; i < starCount; i++) {
                stars.push({
                    x: random(width),
                    y: random(height),
                    size: random(1, 3),
                    speed: random(0.2, 1),
                    brightness: random(150, 255)
                });
            }
        }

        function draw() {
            background(0, 0, 80); // 深蓝色背景，类似Win98

            // 绘制像素风格的网格线
            stroke(70, 70, 120, 50);
            strokeWeight(1);
            let gridSize = 20;
            for (let x = 0; x < width; x += gridSize) {
                line(x, 0, x, height);
            }
            for (let y = 0; y < height; y += gridSize) {
                line(0, y, width, y);
            }

            // 绘制移动的星星
            noStroke();
            for (let i = 0; i < stars.length; i++) {
                let s = stars[i];
                fill(s.brightness);
                rect(s.x, s.y, s.size, s.size); // 使用矩形代替圆形，更像素风

                // 移动星星
                s.y += s.speed;

                // 超出边界，重置到顶部
                if (s.y > height) {
                    s.y = 0;
                    s.x = random(width);
                }
            }

            // 间歇性添加大型闪烁粒子
            if (frameCount % 30 === 0) {
                let x = random(width);
                let y = random(height);
                fill(255, 255, 255, 150);
                rect(x, y, random(3, 5), random(3, 5));
            }
        }

        function windowResized() {
            resizeCanvas(windowWidth, windowHeight);
        }

        const contactBtn = document.getElementById('contactBtn');
        const contactModal = document.getElementById('contactModal');
        const modalCloseBtn = document.getElementById('modalCloseBtn');
        const guideBtn = document.getElementById('guideBtn');
        const guideModal = document.getElementById('guideModal');
        const guideCloseBtn = document.getElementById('guideCloseBtn');

        contactBtn.addEventListener('click', () => {
            contactModal.classList.add('active');
        });

        modalCloseBtn.addEventListener('click', () => {
            contactModal.classList.remove('active');
        });

        contactModal.addEventListener('click', (event) => {
            if (event.target === contactModal) { 
                contactModal.classList.remove('active');
            }
        });

        guideBtn.addEventListener('click', () => {
            guideModal.classList.add('active');
        });

        guideCloseBtn.addEventListener('click', () => {
            guideModal.classList.remove('active');
        });

        guideModal.addEventListener('click', (event) => {
            if (event.target === guideModal) {
                guideModal.classList.remove('active');
            }
        });

        // 添加新的app-content内部动效
        document.addEventListener('DOMContentLoaded', function() {
            const appContent = document.querySelector('.app-content');

            // 创建像素风格的动态装饰元素
            function createPixelElement() {
                const pixel = document.createElement('div');
                pixel.className = 'pixel-decoration';
                pixel.style.position = 'absolute';
                pixel.style.width = Math.floor(Math.random() * 3 + 2) + 'px';
                pixel.style.height = Math.floor(Math.random() * 3 + 2) + 'px';
                pixel.style.backgroundColor = 'rgba(0, 0, 128, 0.2)';
                pixel.style.left = Math.random() * 100 + '%';
                pixel.style.top = Math.random() * 100 + '%';
                pixel.style.zIndex = '0';

                // 随机决定动画类型
                const animType = Math.floor(Math.random() * 3);

                if (animType === 0) {
                    // 闪烁动画
                    pixel.style.animation = `pixelBlink ${Math.random() * 3 + 2}s infinite`;
                } else if (animType === 1) {
                    // 移动动画
                    pixel.style.animation = `pixelFloat ${Math.random() * 5 + 3}s infinite`;
                } else {
                    // 放大缩小动画
                    pixel.style.animation = `pixelPulse ${Math.random() * 4 + 2}s infinite`;
                }

                appContent.appendChild(pixel);

                // 随机存活时间后移除
                setTimeout(() => {
                    if (pixel.parentNode === appContent) {
                        appContent.removeChild(pixel);
                    }
                }, Math.random() * 5000 + 3000);
            }

            // 定期添加新的装饰元素
            setInterval(createPixelElement, 300);

            // 添加扫描线效果
            const scanlines = document.createElement('div');
            scanlines.className = 'scanlines';
            scanlines.style.position = 'absolute';
            scanlines.style.top = '0';
            scanlines.style.left = '0';
            scanlines.style.width = '100%';
            scanlines.style.height = '100%';
            scanlines.style.zIndex = '0';
            scanlines.style.pointerEvents = 'none';
            scanlines.style.backgroundImage = 'linear-gradient(transparent 50%, rgba(0, 0, 0, 0.05) 50%)';
            scanlines.style.backgroundSize = '100% 4px';
            scanlines.style.animation = 'scanline 10s linear infinite';
            appContent.appendChild(scanlines);

            // 偶尔出现的Win98风格图标闪烁
            function createIconFlash() {
                const icons = ['⚙️', '📁', '💾', '🖥️', '📄', '⚠️'];
                const icon = document.createElement('div');
                icon.className = 'win98-icon-flash';
                icon.textContent = icons[Math.floor(Math.random() * icons.length)];
                icon.style.position = 'absolute';
                icon.style.left = Math.random() * 80 + 10 + '%';
                icon.style.top = Math.random() * 80 + 10 + '%';
                icon.style.fontSize = '18px';
                icon.style.opacity = '0';
                icon.style.zIndex = '1';
                icon.style.animation = 'iconFlash 1s ease-in-out';

                appContent.appendChild(icon);

                setTimeout(() => {
                    if (icon.parentNode === appContent) {
                        appContent.removeChild(icon);
                    }
                }, 1000);
            }

            setInterval(createIconFlash, 3000);
        });

        // 添加动画关键帧
        const styleSheet = document.createElement('style');
        styleSheet.textContent = `
            @keyframes pixelBlink {
                0%, 100% { opacity: 0.1; }
                50% { opacity: 0.7; }
            }

            @keyframes pixelFloat {
                0% { transform: translateY(0); }
                50% { transform: translateY(-10px); }
                100% { transform: translateY(0); }
            }

            @keyframes pixelPulse {
                0%, 100% { transform: scale(1); }
                50% { transform: scale(1.5); }
            }

            @keyframes scanline {
                0% { background-position: 0 0; }
                100% { background-position: 0 100px; }
            }

            @keyframes iconFlash {
                0% { opacity: 0; transform: scale(0.5); }
                50% { opacity: 0.7; transform: scale(1.2); }
                100% { opacity: 0; transform: scale(1); }
            }

            .app-content {
                background-color: rgba(192, 192, 192, 0.9) !important;
            }
        `;
        document.head.appendChild(styleSheet);
    </script>
</body>
